import {repeatCases,repeatPages} from './repeat-deliveries-content.mjs';
import {repeatView,startRepeat,resumeRepeat,setRepeatPage,setRepeatArrow,setRepeatCount,beginRepeat,stepRepeat,addRepeatSupport,checkRepeat,repeatCheckMatches,repeatPlan,repeatProgress,repeatProgramLabel,repeatTraceDescription} from './repeat-deliveries-core.mjs';
import {repeatDeliveryMap} from './repeat-deliveries-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const role=(s,id)=>s.marks.find(r=>r.id===id);
const direction=(s,id)=>s.directions.find(d=>d.id===id);
const dirText=(s,id)=>{const d=direction(s,id);return d?`${d.symbol} ${d.label}`:'Choose an arrow';};
const outcome=x=>x===null?'unobserved':x?'fits':'does not fit';
const point=p=>`(${p.x}, ${p.y})`;
const recordHeading=(r,c,i)=>i<r.checks.length-1?'Earlier recorded check':repeatCheckMatches(r,c)?'Latest check of this plan and trace':'Latest check · plan, trace or support changed since';
function key(s){return `<ul class="repeat-map-key">${s.marks.map(r=>`<li><strong>${esc(r.symbol)}</strong> ${esc(r.name)} ${point(s.places[r.id])}</li>`).join('')}</ul>`;}
function goal(s){return `<p class="repeat-goal"><strong>Start:</strong> ${esc(role(s,s.from).name)} ${point(s.places[s.from])} → <strong>Deliver to:</strong> ${esc(role(s,s.to).name)} ${point(s.places[s.to])}.</p>`;}
function mapFigure(s,trace=null,description=s.pictureText,compact=false){return `<figure class="repeat-map${compact?' repeat-map-compact':''}">${repeatDeliveryMap(s,trace,{description})}<figcaption>Circle: start · square: target · dashed outer ring: last shown point. Each grid interval is one ${esc(s.distanceUnit==='model metres'?'model meter':s.distanceUnit)}.</figcaption>${key(s)}<details><summary>Map and traveled-point description</summary><p>${esc(s.pictureText)}</p><p>${esc(description)}</p>${trace?`<p>Shown traveled points: ${trace.points.map(point).map(esc).join(' → ')}.</p>`:''}</details></figure>`;}
function pointer(r,p){if(!r.run)return {kind:'none',label:'No execution pointer before Begin.',arrow:null};if(p.status==='blocked'){const n=r.run.cursor-1;return {kind:'blocked',label:`Blocked: repetition ${Math.floor(n/2)+1}, arrow ${n%2+1}.`,arrow:n%2};}if(p.status==='finished')return {kind:'finished',label:'Finished · the whole repeated program has been attempted.',arrow:null};return {kind:'next',label:`Next: repetition ${Math.floor(r.run.cursor/2)+1}, arrow ${r.run.cursor%2+1}.`,arrow:r.run.cursor%2};}
function blockDisplay(r,p=repeatProgress(r.source,r.block,r.count,r.run)){const at=pointer(r,p);return `<section class="repeat-program" aria-label="The entire two-arrow block repeats"><div class="repeat-bracket"><div class="repeat-block-pair">${r.block.map((id,i)=>`<div class="repeat-arrow-slot${at.arrow===i?' repeat-active-arrow':''}" data-repeat-slot="${i+1}"${at.arrow===i?` data-repeat-highlight="${at.kind}"`:''}><span>Arrow ${i+1}</span><strong>${esc(dirText(r.source,id))}</strong></div>`).join('')}</div><p class="repeat-count-label">Repeat the whole pair <strong>${r.count===null?'?':r.count}</strong> ${r.count===1?'time':'times'}</p></div><p class="repeat-pointer" data-repeat-pointer="${at.kind}">${esc(at.label)}</p></section>`;}
function mapPage(r){return `<h2 id="repeat-prompt" tabindex="-1">${esc(r.source.request)}</h2>${goal(r.source)}${button('data-repeat-page="block"','Next: build the repeated block',true)}<div class="repeat-map-inspect">${mapFigure(r.source)}</div><p>${esc(r.source.story)}</p>${button('data-repeat-page="block"','Build the repeated block',true)}`;}
function blockPage(r){return `<h2 id="repeat-prompt" tabindex="-1">${esc(r.source.request)}</h2>${goal(r.source)}<div class="repeat-turn"><section class="repeat-actions"><h3>Choose the whole two-arrow block</h3>${r.block.map((id,i)=>`<label for="repeat-arrow-${i}">Arrow ${i+1}</label><select id="repeat-arrow-${i}" data-repeat-arrow="${i}"><option value=""${id===null?' selected':''}>Choose an arrow</option>${r.source.directions.map(d=>`<option value="${d.id}"${id===d.id?' selected':''}>${esc(d.symbol)} ${esc(d.label)}</option>`).join('')}</select>`).join('')}<div class="repeat-count-options" role="group" aria-label="How many times to repeat the whole pair">${[2,3].map(n=>button(`data-repeat-count="${n}" aria-pressed="${r.count===n}"`,`Repeat ${n} times`,r.count===n)).join('')}${button(`data-repeat-count="blank" aria-pressed="${r.count===null}"`,'Leave count blank',r.count===null)}</div>${blockDisplay(r)}${button('data-repeat-page="trace"','Next: trace the plan',true)}<p class="tiny">Next only opens Trace. Changing an arrow or count resets the current run; selecting the same value keeps it.</p></section><section>${mapFigure(r.source,null,r.source.pictureText,true)}</section></div>`;}
function counts(p,recorded=false){return `<dl class="repeat-counts"><div><dt>Proposed moves</dt><dd>${p.proposedMoves===null?(recorded?'Not recorded':'Plan incomplete'):p.proposedMoves}</dd></div><div><dt>Attempted arrows</dt><dd>${p.attempted===null?(recorded?'Not recorded':'Not begun'):p.attempted}</dd></div><div><dt>Moves traveled</dt><dd>${p.travelled===null?(recorded?'Not recorded':'Not begun'):p.travelled}</dd></div></dl>`;}
function tracePage(r){const p=repeatProgress(r.source,r.block,r.count,r.run),description=repeatTraceDescription(r.source,r.block,r.count,r.run),complete=p.expanded!==null,canStep=r.run!==null&&!['blocked','finished'].includes(p.status);return `<h2 id="repeat-prompt" tabindex="-1">Fly one arrow of our repeated plan</h2><p class="repeat-current-request">${esc(r.source.request)}</p>${goal(r.source)}<div class="repeat-trace-cluster"><figure class="repeat-trace-map">${repeatDeliveryMap(r.source,p.trace,{description})}<figcaption>Circle: start · square: target.<br>Dashed outer ring: last shown point.</figcaption></figure><section class="repeat-actions">${blockDisplay(r,p)}<div class="repeat-run-controls">${button(`data-repeat-begin${complete?'':' disabled'}`,r.run?'Begin / restart this plan':'Begin this plan')}${button(`data-repeat-step${canStep?'':' disabled'}`,'Fly one arrow',true)}</div><p class="repeat-trace-count-line"><strong>Proposed:</strong> ${p.proposedMoves===null?'incomplete':p.proposedMoves} moves · <strong>Attempted:</strong> ${p.attempted===null?'not begun':p.attempted} arrows · <strong>Travelled:</strong> ${p.travelled===null?'not begun':p.travelled} moves.</p></section></div>${p.status==='incomplete'?'<p class="repeat-run-status">Choose both arrows and a repeat count before Begin.</p>':p.status==='blocked'?'<p class="repeat-run-status">That attempted arrow would leave the grid. The courier stays at the last traveled point; change the block or restart.</p>':p.status==='finished'?'<p class="repeat-run-status">The full program is finished. Keep this result or change the block.</p>':p.status==='unstarted'?'<p class="repeat-run-status">The complete plan is waiting. Begin puts the courier at the start.</p>':''}${button('data-repeat-check','Check / keep this trail',true)} ${button('data-repeat-page="block"','Change the block')}<p class="tiny">Check stays open for incomplete, unstarted and unfinished work. Latest 8 checks remain; a ninth removes the oldest.</p><details id="repeat-trace-details" data-round="${r.id}"><summary>Map key, move counts and traveled points</summary>${key(r.source)}<p>Each grid interval is one model meter; this is a fictional model, not a measured physical route.</p>${counts(p)}<p>${esc(r.source.pictureText)}</p><p>${esc(description)}</p>${p.trace?`<p>Traveled points: ${p.trace.points.map(point).map(esc).join(' → ')}.</p>`:''}</details>`;}
function frozenSource(s){return `<details class="repeat-frozen-source"><summary>Original delivery, map and labels kept with this check</summary><h4>${esc(s.title)}</h4><p>${esc(s.story)}</p><p>${esc(s.request)}</p>${goal(s)}<p>${esc(s.pictureText)}</p>${key(s)}<p>Saved directions: ${s.directions.map(d=>esc(`${d.symbol} ${d.label} (${d.dx}, ${d.dy})`)).join('; ')}.</p><p>${esc(s.help)}</p></details>`;}
function checkRecord(r,c,i){return `<section class="repeat-record" tabindex="-1"><h3>${recordHeading(r,c,i)}</h3><p class="repeat-feedback">${esc(c.feedback)}</p><p><strong>Recorded program:</strong> ${esc(c.programLabel)}.<br><strong>Recorded status:</strong> ${esc(c.status)}.<br><strong>Recorded delivery outcome:</strong> ${outcome(c.deliveryMatch)}.<br><strong>Recorded delivery fulfilled:</strong> ${c.fulfilled?'yes':'no'}.</p>${counts(c,true)}<details><summary>Program, full proposal and traveled prefix kept with this check</summary><p>Input block: ${c.input.block.map(id=>esc(dirText(c.source,id))).join(' · ')}. Count: ${c.input.count===null?'blank':c.input.count}. Run cursor: ${c.input.run===null?'not begun':c.input.run.cursor}.</p><p>Recorded full proposed expansion: ${c.expanded===null?'incomplete':c.expanded.map(id=>esc(dirText(c.source,id))).join(' → ')}.</p><p>Recorded picture description: ${esc(c.pictureText)}</p><p>Recorded trace description: ${esc(c.traceDescription)}</p>${c.trace?`${mapFigure(c.source,c.trace,c.traceDescription,true)}<p>Recorded attempted prefix: ${c.trace.commands.map(id=>esc(dirText(c.source,id))).join(' → ')||'no command attempted'}.</p><p>Recorded trace: ${c.trace.steps} steps, ${c.trace.distance} ${esc(c.source.distanceUnit)}; blocked command ${c.trace.blocked===null?'none recorded':c.trace.blocked}; arrived flag ${c.trace.arrived?'true':'false'}. This arrival field is separate from the recorded delivery outcome.</p>`:'<p>No trace snapshot recorded.</p>'}<p>Support requested by this check: ${esc(c.input.support.join(', ')||'none recorded')}.</p><p class="tiny">These are recorded paths, counts, descriptions and outcomes; they have not been replayed or regraded.</p></details>${frozenSource(c.source)}</section>`;}
function keptPage(r){return `<h2 id="repeat-prompt" tabindex="-1">Our kept repeated delivery</h2>${r.checks.length?checkRecord(r,r.checks.at(-1),r.checks.length-1):'<p>No check is kept yet. The block and trace remain open.</p>'}${button('data-repeat-page="block"','Revise the block',true)} ${button('data-repeat-page="trace"','Return to the trace')}${r.checks.length>1?`<details><summary>Earlier checks (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>checkRecord(r,c,i)).join('')}</details>`:''}`;}
function expansion(r){const plan=repeatPlan(r.source,r.block,r.count);return `<details id="repeat-expansion" data-round="${r.id}"><summary>Show the expanded arrows</summary><p>The entire ordered pair repeats, not only the second arrow. Opening this does not run the plan.</p><p>${esc(repeatProgramLabel(r.source,r.block,r.count))}</p>${plan?`<ol>${plan.map((id,i)=>`<li>Repetition ${Math.floor(i/2)+1}, arrow ${i%2+1}: ${esc(dirText(r.source,id))}</li>`).join('')}</ol>`:'<p>Choose two arrows and a repeat count to have a complete expansion.</p>'}</details>`;}
function catalog(v){const n=Math.max(0,v.rounds.length-11);return `<section class="repeat-catalog"><h2>Choose a delivery job</h2><p>Four fictional repeated-block jobs, all open. Starting makes a separate visit.</p><p class="tiny">Up to 12 readable visits stay here.${n?` Starting now removes the oldest ${n} readable ${n===1?'visit':'visits'}.`:' Earlier visits remain within that limit.'}</p><form id="repeat-start-form"><label for="repeat-case">Delivery job</label><select id="repeat-case" name="case">${repeatCases.map(s=>`<option value="${esc(s.id)}"${v.current?.source.id===s.id?' selected':''}>${esc(s.title)}</option>`).join('')}</select><button type="submit" class="secondary">Start this job</button></form></section>`;}
function history(v){return `${v.rounds.length?`<details><summary>Our repeated-delivery visits (${v.rounds.length})</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-repeat-resume="${r.id}"`,`Visit ${r.id}: ${r.source.title}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable delivery work (${v.earlier.length})</summary><p>The original work remains unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function repeatDeliveriesPage(state){const v=repeatView(state),r=v.current,header=`<header class="page-heading"><a class="back" href="#workshop"><span aria-hidden="true">←</span> Workshop</a> <a class="back" href="#workshop/maps">Cartographer’s Table</a><h1>Repeat a Delivery Block</h1><p>Choose two arrows. Repeat the whole pair, then fly it one arrow at a time.</p></header>`;if(v.status==='unavailable')return `<div class="repeat-page">${header}<section class="repeat-sheet"><h2>Earlier delivery work is safe</h2><p>This saved format cannot be continued here. Maps and other Workshop tools remain open.</p><details><summary>Saved repeated-delivery work</summary><pre>${esc(JSON.stringify(state.repeatDeliveries,null,2))}</pre></details></section></div>`;return `<div class="repeat-page">${header}<section class="repeat-sheet">${r?`<nav class="repeat-tabs" aria-label="Repeated delivery pages">${repeatPages.map(p=>button(`data-repeat-page="${p}" aria-current="${v.page===p?'page':'false'}"`,({map:'Map',block:'Block',trace:'Trace',kept:'Kept trail'})[p],v.page===p)).join('')}</nav><p class="repeat-case-title"><strong>${esc(r.source.title)}</strong>${r.familiar?' · Job visited before':''}</p>`:''}<p id="repeat-status" role="status" tabindex="-1"></p>${r?v.page==='block'?blockPage(r):v.page==='trace'?tracePage(r):v.page==='kept'?keptPage(r):mapPage(r):`<h2 id="repeat-prompt" tabindex="-1">A small block for a repeated flight</h2><p>These model maps have equal grid intervals. The courier follows our chosen arrows; it does not guess the intended destination.</p>${catalog(v)}`}${r?`${expansion(r)}<details id="repeat-help" data-round="${r.id}"><summary>Help us repeat the whole pair</summary><p>${esc(r.source.help)}</p>${hearButton(r.source.help,'Hear the repeated-delivery explanation')}${button('data-repeat-together',r.support.includes('together')?'Thinking together recorded':'We thought together')}</details><details><summary>Choose another delivery job</summary>${catalog(v)}</details>`:''}</section>${history(v)}</div>`;}
export function repeatDeliveriesNotes(state){const v=repeatView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Repeated Deliveries · earlier format</summary><pre>${esc(JSON.stringify(state.repeatDeliveries,null,2))}</pre></details>`;return `<details class="panel repeat-page"><summary>Repeat a Delivery Block (${v.rounds.length} visits)</summary><p>Bounded two-arrow, two-or-three-repeat compose/trace/revise practice. Supplied expansion, labels and manual stepping do not establish independent prediction, counting, writing or general programming. Attempted commands and traveled moves remain distinct; reaching a target during an unfinished program is not completed delivery.</p>${v.rounds.map(r=>`<section><h3>Visit ${r.id}: ${esc(r.source.title)}</h3><p>Job visited before: ${r.familiar?'yes':'no'}. Current program: ${esc(repeatProgramLabel(r.source,r.block,r.count))}. Current cursor: ${r.run===null?'not begun':r.run.cursor}. Support: ${esc(r.support.join(', ')||'none recorded')}.</p><p>Current derived trace description: ${esc(repeatTraceDescription(r.source,r.block,r.count,r.run))}</p>${frozenSource(r.source)}${r.checks.map((c,i)=>checkRecord(r,c,i)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindRepeatDeliveries(state,{save,render,focus}){
 const boundId=repeatView(state).current?.id,sameVisit=el=>el.isConnected&&boundId!==undefined&&repeatView(state).current?.id===boundId;
 const show=(message='',target='#repeat-prompt')=>{const id=repeatView(state).current?.id,open=[...document.querySelectorAll('.repeat-sheet details[id][data-round][open]')].filter(d=>Number(d.dataset.round)===id).map(d=>d.id);save();render();if(repeatView(state).current?.id===id)for(const key of open){const d=document.getElementById(key);if(d)d.open=true;}const status=document.querySelector('#repeat-status');if(status)status.textContent=message;focus?.(target);if(target==='[data-repeat-step]'||target==='[data-repeat-begin]')document.querySelector('.repeat-trace-map')?.scrollIntoView({block:'start',behavior:'instant'});};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b))fn(b);}));
 const saveSupport=code=>{const r=repeatView(state).current;if(!r||r.support.includes(code))return;addRepeatSupport(state,code);save();const h=document.querySelector('.repeat-sheet .repeat-record h3');if(h&&r.checks.length)h.textContent=recordHeading(r,r.checks.at(-1),r.checks.length-1);const status=document.querySelector('#repeat-status');if(status)status.textContent='Support request recorded.'+(h?' '+h.textContent+'.':'');};
 document.querySelector('#repeat-start-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.isConnected||repeatView(state).current?.id!==boundId)return;const r=startRepeat(state,new FormData(form).get('case'));show(r?'A repeated-delivery job is ready.':'A new visit cannot be created because its saved visit numbers have reached the supported limit.',r?'#repeat-prompt':'#repeat-status');});
 document.querySelectorAll('[data-repeat-resume]').forEach(b=>b.addEventListener('click',()=>{if(!b.isConnected||repeatView(state).current?.id!==boundId)return;show(resumeRepeat(state,Number(b.dataset.repeatResume))?'Earlier delivery opened with its own map and plan.':'That visit could not be opened.');}));
 bind('[data-repeat-page]',b=>{setRepeatPage(state,b.dataset.repeatPage);show();});
 document.querySelectorAll('[data-repeat-arrow]').forEach(select=>select.addEventListener('change',()=>{if(!sameVisit(select))return;const r=repeatView(state).current,index=Number(select.dataset.repeatArrow),value=select.value||null,changed=r.block[index]!==value;setRepeatArrow(state,index,value);show(changed?'Arrow changed; the current run was reset. Earlier checks remain.':'The same arrow remains selected; the current run is retained.',`[data-repeat-arrow="${index}"]`);}));
 bind('[data-repeat-count]',b=>{const value=b.dataset.repeatCount==='blank'?null:Number(b.dataset.repeatCount),changed=repeatView(state).current.count!==value;setRepeatCount(state,value);show(changed?'Repeat count changed; the current run was reset.':'The same count remains selected; the current run is retained.',`[data-repeat-count="${b.dataset.repeatCount}"]`);});
 bind('[data-repeat-begin]',()=>{const ok=beginRepeat(state);show(ok?'The courier is at the start. Next: repetition 1, arrow 1.':'Choose both arrows and a count before Begin.',ok?'[data-repeat-step]':'[data-repeat-begin]');});
 bind('[data-repeat-step]',()=>{const ok=stepRepeat(state),r=repeatView(state).current,p=repeatProgress(r.source,r.block,r.count,r.run);show(ok?pointer(r,p).label:'No arrow was attempted. Begin a complete plan or revise a stopped plan.',['blocked','finished'].includes(p.status)?'[data-repeat-begin]':'[data-repeat-step]');});
 bind('[data-repeat-check]',()=>{const c=checkRepeat(state);if(c)setRepeatPage(state,'kept');show(c?'The actual program and attempted prefix are kept.':'This check could not be kept.',c?'.repeat-record':'#repeat-status');});
 bind('[data-repeat-together]',()=>{saveSupport('together');show('Noted: you thought about this together.','[data-repeat-together]');});
 for(const [id,code]of [['repeat-help','help'],['repeat-expansion','expansion']]){const fold=document.getElementById(id);fold?.addEventListener('toggle',()=>{if(fold.open&&sameVisit(fold)&&Number(fold.dataset.round)===boundId)saveSupport(code);});}
 document.querySelectorAll('.repeat-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b))saveSupport('audio');}));
}
